BACKEND_NOTE="def _vm_backend_note(record,out,err,error):\n import base64,json\n keys={'argv','exit_code','seconds','time_limit','output_limit','group_absence_verified','stdout_bytes','stdout_sha256','stderr_bytes','stderr_sha256'}\n C.need(set(record)==keys and record['output_limit']==1024**2,'original backend receipt required')\n for side,data in (('stdout',out),('stderr',err)):\n  C.need(record[side+'_bytes']==len(data) and record[side+'_sha256']==C.sha(data),'original backend stream join')\n result=None\n try:\n  v=C.decode(out)\n  if set(v)=={'status','error_type','error','packages_committed','commit_started','recovery','rollback'} and v['status']=='FAIL' and v['packages_committed'] is False and v['commit_started'] is False and v['recovery']=='DISPOSE_OWNED_COPY_IF_COMMIT_OR_CLEANUP_UNCERTAIN' and v['rollback']=='NOT_CLAIMED' and type(v['error_type'])is str and len(v['error_type'])<=128 and type(v['error'])is str and len(v['error'])<=1024:\n   raw=v['error'].encode('utf8');result=dict(status='FAIL',error_type=v['error_type'],error=v['error'][:96],error_utf8_bytes=len(raw),error_sha256=C.sha(raw),truncated=len(v['error'])>96,commit_started=False,packages_committed=False)\n except (ValueError,KeyError,TypeError,UnicodeError):pass\n def phase_summary(data):\n  # Data-only projection of existing records; never inspect a root again.\n  stages=('source-revalidation','tree-and-aux-observation','tree-observe','complete-capability-map','capability-scan','copy-with-capability-restoration','copy-data','diagnostic-limit')\n  events=('BEGIN','END','FAIL','FURTHER_PHASE_RECORDS_OMITTED')\n  records=[];stats={};stack=[];first=None;previous=None\n  try:\n   for line in data.splitlines():\n    if not line.startswith(b'APPS574_PHASE '):continue\n    if len(line)>511 or len(records)>=96:raise ValueError('phase record bound')\n    v=json.loads(line[len(b'APPS574_PHASE '):]);base={'schema_version','seq','stage','event','monotonic_ns'}\n    if type(v)is not dict or set(v)not in (base,base|{'error_type','error_reason'}):raise ValueError('phase fields')\n    if type(v['schema_version'])is not int or v['schema_version']!=1 or type(v['seq'])is not int or v['seq']!=len(records)+1 or type(v['monotonic_ns'])is not int or not 0<=v['monotonic_ns']<2**63:raise ValueError('phase scalar')\n    stage=stages.index(v['stage']);event=events.index(v['event']);now=v['monotonic_ns']\n    if previous is not None and now<previous:raise ValueError('phase clock order')\n    if first is None:first=now\n    if stage==7 or event==3:\n     if (stage,event,v['seq'])!=(7,3,96):raise ValueError('phase limit marker')\n    else:\n     counts=stats.setdefault(stage,[0,0,0,0]);counts[event]+=1\n     if event==0:stack.append((stage,now))\n     else:\n      if not stack or stack[-1][0]!=stage:raise ValueError('phase nesting')\n      counts[3]+=now-stack.pop()[1]\n    records.append([v['seq'],stage,event,now-first]);previous=now\n   if not records:return None\n   return dict(version=1,records=len(records),first_ns=first,stages=[[s,*counts]for s,counts in sorted(stats.items())],last=records[-2:])\n  except (ValueError,TypeError,KeyError,IndexError):return dict(version=1,status='INVALID_PHASE_RECORDS')\n tail=err[-64:]\n value=dict(schema_version=1,event='prepare_copy_backend_failure',supervisor=record,result=result,stderr_tail=dict(bytes=len(tail),sha256=C.sha(tail),base64=base64.b64encode(tail).decode(),truncated=len(err)>64),supervisor_error=None if error is None else type(error).__name__,acceptance_authority=False,cleanup_authority=False)\n summary=phase_summary(err)\n if summary is not None:\n  candidate=dict(value,schema_version=2,phase_summary=summary)\n  if len(('APPS574_BACKEND_FAILURE '+json.dumps(candidate,sort_keys=True,separators=(',',':'),ensure_ascii=True)).encode())<=1900:value=candidate\n note='APPS574_BACKEND_FAILURE '+json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True)\n C.need(len(note.encode())<=1900,'complete backend note must fit original2KiB tail');return note\n_vm_original_call=H.Calls.call\ndef _vm_backend_call(self,argv,*,seconds=610,expected=0):\n original=self.api;captured=[]\n def capture(*a,**kw):\n  row=original.run_command(*a,**kw);captured.append(row);return row\n self.api=types.SimpleNamespace(run_command=capture)\n try:return _vm_original_call(self,argv,seconds=seconds,expected=expected)\n except Exception as error:\n  if list(map(str,argv[:5]))==['/usr/bin/python3','-I','-B','/execution/scripts/ci/apps7-full574-repair-native/transaction.py','prepare-copy'] and len(captured)==1:\n   try:error.add_note(_vm_backend_note(*captured[0]))\n   except Exception:pass # Diagnostic loss cannot replace the original exception.\n  raise\n finally:self.api=original\nH.Calls.call=_vm_backend_call\n"

